"""Create editorial pages, free planning resources, and partnership information."""
from pathlib import Path
from build_site import ROOT,layout,esc
def write(path,title,description,body):
    file=ROOT/path;file.parent.mkdir(parents=True,exist_ok=True);file.write_text(layout(path,title,description,body))
def article(path,title,description,body,planner='/#builder'):
    write('guides/'+path,title,description,'<div class="ey">Build planning guide</div><h1>'+esc(title)+'</h1><p>'+esc(description)+'</p>'+body+'<div class="actions"><a class="btn" href="'+esc(planner)+'" data-event="guide_to_planner">Open the Free Build Planner →</a><a class="btn ghost" href="/resources/build-workbook.html">Free Project Workbook</a></div><p class="mini">Written by BuildMyBeast · Updated September 29, 2026. Estimates are planning examples, not quotes or fitment approval.</p>')
article('2007-chevy-tahoe-street-build.html','Plan a 2007 Chevrolet Tahoe Street Build','Use BDK as real inspiration, then organize your own wheels, lighting, exterior, and audio priorities.','''<h2>Start with the direction, then identify exact parts</h2><p><a href="/builds/bdk.html">BDK</a> combines 26-inch wheels, window tint, refreshed headlights and taillights, Texas Edition trim, and three Memphis subs in a custom ported box. Those submitted details show the direction of the project; they do not provide tire dimensions, offsets, amplifier specifications, or exact part numbers.</p><h2>Build your research list</h2><ol><li>Record your Tahoe's year, trim, drivetrain, engine, and current modifications.</li><li>For wheels, ask the supplier to confirm the complete wheel-and-tire fitment against your exact vehicle and suspension setup.</li><li>For audio, get an installation plan covering enclosure design, wiring, protection, and electrical requirements.</li><li>For lighting and exterior parts, identify exact assemblies, connections, and local use requirements before ordering.</li></ol><h2>Separate your budget into four buckets</h2><div class="table-wrap"><table><thead><tr><th>Bucket</th><th>What to include</th></tr></thead><tbody><tr><td>Parts</td><td>Main products plus required supporting hardware</td></tr><tr><td>Installation</td><td>Shop labor, fabrication, and setup</td></tr><tr><td>Other purchase costs</td><td>Shipping, taxes, and supplies from your actual quotes</td></tr><tr><td>Contingency</td><td>A reserve you choose for unexpected work</td></tr></tbody></table></div><h2>Compare two directions</h2><p>Save your plan to My Garage, duplicate it, and name the versions Daily Tahoe and Show Tahoe. Change one category at a time, then use Compare Builds to see the cost difference. Keep your real quotes in the workbook rather than treating the planner's estimate as a vendor price.</p>''','/?type=suv&make=Chevrolet&model=Tahoe&year=2007&style=Street%20%2F%20Show&budget=10000&u_wheels=2800&u_audio=3500&u_exterior=700&u_lighting=350&utm_source=build_guides&utm_medium=guide&utm_campaign=2007_tahoe#builder')
article('26-inch-tahoe-wheel-planning.html','26-Inch Wheels on a Tahoe: Questions Before Buying','A real Tahoe build can inspire the look. Exact wheel, tire, and vehicle measurements determine whether your own setup works.','''<h2>Diameter is only one part of fitment</h2><p>Do not order a wheel solely because another Tahoe uses the same diameter. Confirm width, offset, bolt pattern, center bore, load capacity, tire choice, and clearance for your exact vehicle. Tire Rack's fitment overview explains that offset affects tire and suspension clearance and that load capacity must suit the vehicle's axle ratings.</p><h2>Ask your supplier these questions</h2><ul><li>What exact wheel and tire part numbers are being quoted?</li><li>Does the setup suit my model year, drivetrain, brakes, and suspension?</li><li>Will clearance be checked through steering travel and suspension movement?</li><li>What hardware, sensors, installation work, or other changes are required?</li><li>What is the return policy if the proposed combination does not fit?</li></ul><h2>Budget the whole package</h2><p>Collect separate quotes for wheels, tires, installation, sensors and required hardware. Record them together in the project workbook. Compare that actual package price with a smaller-diameter alternative before choosing.</p><h2>Real build inspiration</h2><p><a href="/builds/my-hoe.html">My Hoe</a> and <a href="/builds/bdk.html">BDK</a> both list 26-inch wheels. Their gallery descriptions do not establish a guaranteed fitment specification for your Tahoe.</p><p class="mini">Source: <a href="https://www.tirerack.com/upgrade-garage/we-find-out-what-fits-so-you-can-install-with-confidence" rel="noopener">Tire Rack: how fitment is evaluated</a>.</p>''','/?type=suv&make=Chevrolet&model=Tahoe&utm_source=build_guides&utm_medium=guide&utm_campaign=tahoe_wheels#builder')
article('tahoe-audio-build-planning.html','Tahoe Audio Build Planning: More Than Subwoofer Count','Organize your sound goals, enclosure, supporting equipment, and installation budget before buying an audio system.','''<h2>Describe the result you want</h2><p>Write down whether you want clearer daily listening, more bass, or a show-focused system. Note the cargo space and seats you want to retain. A build with several subwoofers is an example of one owner's choices; count alone does not define the equipment or supporting installation your project needs.</p><h2>Ask for one complete installation proposal</h2><ul><li>Exact subwoofer and amplifier models, and a compatible system design</li><li>Enclosure dimensions, placement, and construction</li><li>Integration with the existing radio and controls</li><li>Appropriate wiring, grounding, and power-wire protection</li><li>An assessment of electrical-system requirements</li><li>Installation, tuning, warranty, and support</li></ul><p>Crutchfield explains that an inline fuse protects amplifier power wiring and the vehicle. Use manufacturer instructions and a qualified installer for the specific wiring and electrical design.</p><h2>Keep sound upgrades separate from cosmetic spending</h2><p>Create an Audio First garage version and a Balanced Build version. Compare audio and exterior allocations, then add actual shop quotes to the workbook. Include supporting equipment in your quote instead of budgeting only for the subwoofers.</p><p class="mini">Source: <a href="https://www.crutchfield.com/learn/car-amplifier-power-wire-fuses.html" rel="noopener">Crutchfield: amplifier power-wire protection</a>. Inspiration: <a href="/builds/bdk.html">BDK</a> and <a href="/builds/my-hoe.html">My Hoe</a>.</p>''','/?type=suv&make=Chevrolet&model=Tahoe&style=Audio%20Monster&budget=10000&u_audio=3500&utm_source=build_guides&utm_medium=guide&utm_campaign=tahoe_audio#builder')
article('daily-driver-vs-show-build.html','Daily Driver vs. Show Build: Compare Before Spending','Use two versions of the same project to decide where comfort, appearance, and budget matter most.','''<h2>Write down how the vehicle will be used</h2><p>Record your commute, passengers, cargo, roads, parking constraints, and any towing needs. A project you drive every day has different practical priorities from one built mainly for display.</p><h2>Create two saved plans</h2><ol><li>Choose your vehicle and save the first plan in My Garage.</li><li>Rename it Daily Driver.</li><li>Duplicate the build and rename the copy Show Build.</li><li>Change the upgrade levels in the copy and save the changes.</li><li>Use Compare Builds to review categories, cost estimates, and budget remaining.</li></ol><h2>Compare consequences alongside costs</h2><p>For each upgrade, write down the installation quote, maintenance implications, reversibility, and effect on the vehicle's intended use. Ask a qualified shop about fitment and practical tradeoffs for the exact components you are considering.</p><h2>Choose a first phase you can finish</h2><p>Pick a coherent group of upgrades with supporting work included. Save the remaining ideas for a later phase rather than buying incomplete pieces from several categories.</p>''')
article('first-motorcycle-build-planning.html','Planning Your First Motorcycle Build','Organize your motorcycle project around condition, intended use, compatible parts, and a complete budget.','''<h2>Start with the bike you have</h2><p>Record the make, model, year, current equipment, and service history. Before planning appearance or performance changes, have unresolved mechanical issues assessed.</p><h2>Separate maintenance from modifications</h2><p>Use the Motorcycle Safety Foundation's T-CLOCS checklist as a starting inspection resource. Keep maintenance, riding equipment, optional modifications, and installation as separate budget categories.</p><h2>Use motorcycle-specific parts information</h2><p>Confirm the exact application and manufacturer instructions for each proposed component. Tire and wheel changes need motorcycle-specific guidance; do not apply a car build's assumptions to a motorcycle.</p><h2>Compare your build directions</h2><p>Select Motorcycle in the planner, save your baseline, and duplicate it for a second direction. The planner's figures help organize your ideas; actual parts and labor require quotes for your specific bike.</p><p class="mini">Resources: <a href="https://msf-usa.org/documents/library/t-clocs-pre-ride-inspection-checklist/">MSF T-CLOCS inspection checklist</a> and <a href="https://msf-usa.org/documents/library/motorcycle-tire-guide/">MSF motorcycle tire guide</a>.</p>''')
article('vehicle-led-refresh-budget.html','Budgeting a Vehicle LED Refresh','Make a lighting inventory and quote the complete upgrade before choosing a look.','''<h2>List each lighting location</h2><p>Separate headlights, taillights, interior lamps, and decorative lighting. Record what is currently installed and whether you are replacing a bulb, an assembly, or adding a new circuit.</p><h2>Identify the exact application</h2><p>Give the supplier your year, make, model, trim, and existing lighting equipment. Ask for the exact product application and installation instructions. A product's appearance or a general LED label does not establish compatibility.</p><h2>Collect a complete quote</h2><ul><li>Main lamps or assemblies</li><li>Required adapters, controllers, wiring, and protection</li><li>Installation and setup</li><li>Any additional supporting work identified by the installer</li></ul><h2>Keep road use and decorative use separate</h2><p>Confirm that the exact lighting setup is suitable for its intended use and location before purchase. Ask the supplier and installer to identify any use restrictions that apply to the proposed parts.</p><p>See <a href="/builds/shade.html">Shade</a> for a member project that includes a lighting refresh, then create your own plan and quote list.</p>''')
fields=[('project','Project nickname'),('vehicle','Vehicle: year, make, model, configuration'),('goal','Build goal and intended use'),('budget','Target budget and contingency'),('baseline','Maintenance and baseline condition'),('parts','Parts list: manufacturer, exact part number, quote, date'),('fitment','Fitment questions and confirmed answers'),('labor','Shop quotes and supporting work'),('phases','Phases: work, planned cost, target date'),('spending','Actual spending: item, cost, date'),('progress','Progress notes and next action')]
form=''.join('<div class="field"><label for="'+key+'">'+esc(label)+'</label><textarea id="'+key+'" name="'+key+'" maxlength="10000"></textarea></div>' for key,label in fields)
write('resources/build-workbook.html','Free Vehicle Build Project Workbook','Record real quotes, fitment questions, build phases, and actual spending in a printable project workbook.','<div class="ey">Free planning resource</div><h1>Your build, organized.</h1><p>Use the planner for upgrade estimates and this workbook for actual quotes, decisions, and progress.</p><p class="mini">Your entries stay in this browser. They are not submitted to BuildMyBeast. Download a backup before clearing browser data or switching devices.</p><div class="actions"><button class="btn" id="printWorkbook" type="button">Print / Save as PDF</button><button class="btn ghost" id="downloadWorkbook" type="button">Download Workbook Backup</button><label class="btn ghost" for="importWorkbook">Import Workbook Backup</label><input hidden class="no-print" id="importWorkbook" type="file" accept=".json,application/json"></div><p id="workbookStatus" role="status" class="mini"></p><form id="workbook">'+form+'</form><div class="actions"><a class="btn" href="/#builder">Open Build Planner</a><a class="btn ghost" href="/#buildAlerts">Get Free Build Alerts</a></div><script src="/resources/workbook.js"></script>')
write('partners/index.html','Automotive Shop & Brand Partnerships','Connect your automotive services with enthusiasts planning their next vehicle project.','''<div class="ey">Work with BuildMyBeast</div><h1>Help builders turn a plan into a project.</h1><p>We welcome conversations with wheel and tire shops, audio installers, tint businesses, lighting specialists, and fabrication shops.</p><div class="grid"><section class="card"><h2>Shop profiles</h2><p>Discuss a profile with your location, services, contact information, and completed-project photos you have permission to share.</p></section><section class="card"><h2>Relevant sponsorships</h2><p>Discuss clearly labeled sponsorships connected to the vehicles and upgrades you serve.</p></section><section class="card"><h2>Project inquiries</h2><p>Explore a pilot for visitors who explicitly choose to contact a named shop about their build.</p></section></div><h2>Start a partnership conversation</h2><p>Email your business name, service area, website, specialties, and the kind of partnership you are interested in. We will discuss scope and pricing before any paid placement begins.</p><div class="actions"><a class="btn" data-event="partner_inquiry_click" href="mailto:contact@buildmybeast.com?subject=BuildMyBeast%20shop%20partnership">Contact BuildMyBeast →</a></div><p class="mini">We do not promise traffic, leads, or sales. Paid placements will be labeled. Sponsorship does not certify product fitment or replace independent purchasing decisions.</p>''')
write('builds/member.html','Approved Community Build','Explore a recently approved member build and open it in the gallery.','''<p id="memberStatus" role="status">Loading member build…</p><div id="memberContent" hidden><div class="ey">Approved member build</div><h1 id="memberTitle"></h1><p id="memberVehicle"></p><img id="memberPhoto" class="photo" alt=""><div id="memberPhotos"></div><h2>Submitted modifications</h2><p id="memberMods"></p><div class="actions"><button class="btn ghost" data-share>Share This Build</button><button class="btn ghost" data-copy>Copy Link</button><a class="btn" id="memberPlanner" href="/#gallery">Open Gallery &amp; Plan a Similar Build →</a></div><p class="mini">Submitted details are inspiration, not verified product specifications.</p></div><a href="/#gallery">Return to the Gallery</a><script src="/gallery/config.js"></script><script src="/builds/member.js"></script>''')
